    // 보기 카드(emotion pick) — 갈래 보기(branch)는 휴대폰에서 누름 영역이 44px보다 작아 출구에서는 고르기 카드로 묻는다
    const CRC = (ix) => ix.map((i) => ({ id: CR[i].id, text: CR[i].text, why: CR[i].result }));
