          art: { draw: 'a paper-cut rainy evening alley with one broken street lamp, a large parked van at the corner and a student in dark clothes stepping out as a car brakes on the wet road', banner: '무엇이 겹쳤을까?', extra: [{ motif: 'cloud', x: 300, y: 96 }] },
